SELECT wt.id AS wallet_trade_id, wt.symbol, wt.execution_reason, wt.executed_at, s1.id AS sig_1m, s1.candle_open_time AS c1_open, s1.generated_at AS gen_1m, s5.id AS sig_5m_same_close, s5.generated_at AS gen_5m, TIMESTAMPDIFF(MICROSECOND, s1.generated_at, s5.generated_at) / 1000 AS ms_5m_after_1m, s5.decision AS d5_same, s5.original_decision AS od5_same, p5.id AS prev_5m, p5.decision AS d5_prev, p5.original_decision AS od5_prev FROM crypto_ai.wallet_trade wt JOIN crypto_ai.trade_signal s1 ON s1.id = wt.signal_id AND s1.interval_code = '1m' JOIN crypto_ai.trade_signal s5 ON s5.symbol = s1.symbol AND s5.interval_code = '5m' AND s5.candle_open_time = s1.candle_open_time - INTERVAL 4 MINUTE LEFT JOIN crypto_ai.trade_signal p5 ON p5.symbol = s1.symbol AND p5.interval_code = '5m' AND p5.candle_open_time = s1.candle_open_time - INTERVAL 9 MINUTE WHERE wt.side = 'BUY' AND wt.executed_at BETWEEN '2026-10-09 00:00:00' AND '2026-10-19 18:00:00' ORDER BY wt.id LIMIT 200;